/* ---------- Banco de ASO (15 preguntas) ---------- */
/* exp = respuesta esperada por ASO (resumida); lux = como se responde con lo que Lux hizo de verdad. */
const ASO = [
  { n: 1, unit: "U1", q: "¿Qué tipo de hipervisor es VirtualBox y en qué se diferencia de uno como ESXi? ¿Qué modo de red usaron para la VM y por qué?",
    exp: "VirtualBox es tipo 2 (sobre un SO anfitrión); ESXi es tipo 1 (bare-metal, sobre el hardware, rinde más y es de centros de datos). Con adaptador puente la VM recibe IP de la red real y otros equipos la alcanzan; con NAT sale a Internet pero queda oculta.",
    lux: "Explicar la diferencia tipo 1 y tipo 2 y decir el hipervisor y el modo de red que se usaron de verdad.",
    cmds: ["ip -br a"], todo: "No está documentado en el repo: completar qué hipervisor y qué modo de red usó el equipo en la VM del ITI." },
  { n: 2, unit: "U1", q: "Explicá cómo funciona la autenticación por clave pública en SSH. ¿Qué clave queda en el servidor y cuál en tu equipo?",
    exp: "Par de claves con ssh-keygen -t ed25519. La pública va al servidor en ~/.ssh/authorized_keys; la privada nunca sale del equipo. El servidor plantea un desafío que solo se responde con la privada. Permisos: 700 en ~/.ssh y 600 en authorized_keys.",
    lux: "En Lux el acceso es solo por llave: PasswordAuthentication no, PermitRootLogin no, AllowGroups sgrsi-tecnicos sudo, MaxAuthTries 3, puerto 52205. Se agrega una llave con `admin.sh ssh llave-agregar <usuario> <archivo.pub>` y el script se niega a endurecer si nadie tiene llave instalada.",
    cmds: ["ssh-keygen -t ed25519", "ssh-copy-id usuario@IP", "ssh usuario@IP"] },
  { n: 3, unit: "U2", q: "¿Por qué eligieron ese sistema operativo para el servidor? Dame tres criterios concretos.",
    exp: "Soporte y ciclo de vida (LTS), comunidad y documentación, compatibilidad y costo, y versión sin entorno gráfico (menos RAM y menos superficie de ataque).",
    lux: "Debian 13 «Trixie» (netinst), elegido tras comparar con Ubuntu Server LTS y Rocky Linux: ciclo estable y predecible, repositorios oficiales con todo lo necesario (Nginx, PostgreSQL, Podman), comunidad y documentación, compatibilidad total con Podman rootless, y sin snaps ni servicios extra de Ubuntu.",
    cmds: ["cat /etc/os-release"] },
  { n: 4, unit: "U2", q: "¿Para qué sirve la memoria swap? ¿Qué particiones tiene tu servidor y por qué?",
    exp: "Swap: extensión de la RAM en disco; evita quedarse sin memoria pero es más lenta. Particiones típicas: /, /boot, swap y opcionalmente /var o /home separadas. Kernel y módulos: lsmod y modprobe.",
    lux: "Esquema documentado: /boot 512 MB ext4, swap 2 GB (para 4 a 8 GB de RAM) y / con el resto en ext4. No se separó /var; si preguntan, decir que separarlo evitaría que los logs o la base llenen la raíz y que es una mejora posible.",
    cmds: ["free -h", "lsblk", "df -h"], todo: "ARQUITECTURA.md marca estas secciones como referencia de la instalación original: confirmar que coinciden con el servidor real." },
  { n: 5, unit: "U3", q: "¿Cómo verificás si Apache (o MySQL) está funcionando y cómo hacés que arranque solo al encender el servidor?",
    exp: "systemctl status <servicio>; sudo systemctl enable --now <servicio>; journalctl -u <servicio>; restart reinicia y reload recarga sin cortar conexiones.",
    lux: "Lux no usa Apache ni MySQL: usa Nginx (en el host y dentro del contenedor web) y PostgreSQL en un contenedor. Se verifica con `systemctl status nginx` y `admin.sh deploy estado`. El arranque automático del stack lo da la unidad de usuario lux-stack.service con linger: `systemctl --user enable --now lux-stack.service`. Logs: `journalctl --user -u lux-stack` y `admin.sh deploy logs api 50`.",
    cmds: ["systemctl status", "systemctl enable --now", "journalctl -u", "admin.sh deploy estado"] },
  { n: 6, unit: "U3", q: "Describí los pasos para instalar el SGRSI en el servidor sin Docker, desde cero.",
    exp: "Actualizar, instalar paquetes del stack, habilitar servicios, copiar el código con dueño y permisos correctos, crear base y usuario propio con permisos mínimos, importar el .sql, configurar la conexión, abrir 80 y 443 y probar desde otro equipo.",
    lux: "Camino de Lux (contenedores): instalar Debian 13, apt (nginx, podman, ufw, git, certbot), clonar el repo en /opt/sgrsi/lux, crear /etc/sgrsi/lux.env con modo 600 (secretos con openssl rand), `admin.sh firewall aplicar-base`, `admin.sh ssh aplicar`, `admin.sh deploy up` (construye, migra y espera /ready) y probar con ops/verificar-redes.sh. Si piden «sin contenedores», explicar que Lux eligió Podman y por qué.",
    cmds: ["apt update && apt upgrade", "admin.sh deploy up", "curl http://localhost:4111/ready"] },
  { n: 7, unit: "U4", q: "¿Por qué un servidor necesita IP estática? ¿Dónde y cómo la configuraste?",
    exp: "Con DHCP la IP puede cambiar y se rompen usuarios, scripts y reglas de firewall. En Debian se configura en /etc/network/interfaces (o systemd-networkd), en Ubuntu con Netplan. Hay que poner IP con máscara, gateway y DNS. Alternativa: reserva DHCP por MAC.",
    lux: "El módulo scripts/lib/red.sh detecta el backend (ifupdown o systemd-networkd) y escribe /etc/network/interfaces o /etc/systemd/network/10-sgrsi.network con la IP, el prefijo, el gateway y el DNS de /etc/sgrsi/sgrsi.conf; `admin.sh red config` muestra lo que aplicaría y `admin.sh red verificar` compara la IP actual. ATENCIÓN: docs/ARQUITECTURA.md sección 4.3 dice Netplan, pero en Debian el script usa ifupdown o networkd: responder con lo que hace el script.",
    cmds: ["ip -br a", "ip route", "ping"], todo: "Corregir ARQUITECTURA.md 4.3 (Netplan) o confirmar que el servidor real usa Netplan." },
  { n: 8, unit: "U4", q: "¿Qué puertos tiene abiertos tu servidor y por qué cada uno? ¿Por qué no se abre el 3306?",
    exp: "22 (o el puerto SSH elegido), 80 y 443. Política: denegar todo lo entrante. El puerto de la base no se abre porque solo lo usa la aplicación en el mismo servidor. Se verifica con ufw status verbose y ss -tlnp.",
    lux: "Abiertos: 80 (redirección a HTTPS), 443 (frontend y API) y SSH en 52205 con `ufw limit`. Lux usa PostgreSQL, así que el puerto de la base es el 5432, no el 3306: no se abre porque está en la red interna lux_data y solo la ven la API y las migraciones. El script marca como prohibidos 5432, 3306, 4111 y 8080 y los verifica; el 8080 de web solo escucha en 127.0.0.1.",
    cmds: ["ufw status verbose", "ss -tlnp", "admin.sh firewall estado"] },
  { n: 9, unit: "U4", q: "¿Qué es un virtual host en Apache y para qué sirve en el proyecto?",
    exp: "Permite que un mismo servidor atienda varios sitios por nombre de dominio o por puerto; define ServerName, DocumentRoot y logs. En Ubuntu: sites-available, a2ensite, apachectl configtest y recarga.",
    lux: "Lux usa Nginx: el equivalente es el bloque server{} con server_name, que en el host termina TLS y hace proxy a 127.0.0.1:8080, y dentro del contenedor web sirve la SPA y hace proxy de /graphql a la API. La validación equivalente es `nginx -t` antes de recargar. Permite publicar lux.eternum.lat y dev.eternum.lat en el mismo servidor.",
    cmds: ["nginx -t", "systemctl reload nginx"] },
  { n: 10, unit: "U5", q: "¿Qué cambios hiciste en la configuración de SSH para endurecerlo? ¿Cómo comprobás que se aplicaron?",
    exp: "PasswordAuthentication no, PermitRootLogin no, PubkeyAuthentication yes, opcionales Port, AllowUsers/AllowGroups y MaxAuthTries. Validar con sshd -t, no cerrar la sesión actual y comprobar con sshd -T. Complementos: Fail2Ban, ssh-agent.",
    lux: "Archivo drop-in /etc/ssh/sshd_config.d/99-sgrsi.conf: Port 52205, PermitRootLogin no, PasswordAuthentication no, AllowGroups sgrsi-tecnicos sudo y MaxAuthTries 3. Además `ufw limit` en el puerto SSH frena fuerza bruta (6 conexiones por 30 s). No se usa Fail2Ban. Se valida con sshd -t y se comprueba con sshd -T; los tests bats validan el fragmento con el sshd real.",
    cmds: ["sudo sshd -t", "sudo sshd -T", "admin.sh ssh aplicar"] },
  { n: 11, unit: "U6", q: "¿Qué respalda tu script, cada cuánto se ejecuta y cuánto tiempo se guardan las copias?",
    exp: "Base con mysqldump (no copiar archivos en caliente) y código y configuración con tar.gz. Completo, incremental y diferencial. Cron con cinco campos. Retención por ejemplo 7 diarias y 4 semanales.",
    lux: "backup.sh genera lux_<id>.sql.gz (dump de PostgreSQL), archivos_<id>.tar.gz (configuración sin secretos), secretos_<id>.tar.gz.gpg (si hay clave) y un .sha256. Todos son respaldos completos. Cron: diario 03:00 (`0 3 * * *`). Retención: 7 diarios y 4 semanales con rotacion.sh. Los archivos se arman primero en .tmp y se mueven al destino solo si pasan las comprobaciones.",
    cmds: ["pg_dump", "tar -czf", "crontab -l", "gzip -t", "sha256sum"] },
  { n: 12, unit: "U7", q: "Explicá cómo está organizado tu script final. ¿Qué tendrías que hacer para agregar un módulo nuevo, por ejemplo de monitoreo?",
    exp: "Un main que carga módulos con source, muestra el menú y acepta parámetros para cron; un archivo de configuración; una carpeta de módulos con funciones, variables local y validación; un módulo común. Para agregar monitoreo: crear el módulo, hacer source y sumar una opción al menú.",
    lux: "scripts/admin.sh es un despachador que descubre solo los módulos de scripts/lib/. Un módulo nuevo es un archivo lib/<nombre>.sh que define <nombre>_main, <nombre>_descripcion y <nombre>_ayuda: admin.sh lo encuentra sin editarse, y si un módulo no carga lo informa y sigue con los demás. lib/comun.sh trae logging, --dry-run, validaciones, reintentos y locks. Configuración en /etc/sgrsi/sgrsi.conf. Códigos de salida: 0, 1, 2, 75 (fallo temporal) y 78 (configuración).",
    cmds: ["admin.sh --dry-run ufw aplicar-base", "bats bats/*.bats"] },
  { n: 13, unit: "U7", q: "En un if de bash, ¿qué se evalúa? Explicá con una función de tu script cómo detecta si algo salió mal.",
    exp: "Se evalúa el código de salida: 0 es éxito y entra por then. $? guarda el último. Con tuberías hay que usar set -o pipefail o PIPESTATUS. return termina una función y exit el script. Comandos de diagnóstico: df, free, top, uptime, systemctl --failed, journalctl -p err.",
    lux: "Los módulos devuelven códigos y backup.sh usa `set -euo pipefail`, así un pg_dump que falla dentro de `| gzip` no se oculta. Las funciones retornan 0 o un código propio y admin.sh traduce a las salidas 0, 1, 2, 75 y 78. Monitoreo: `backup.sh estado` falla con ERROR si el último respaldo tiene más de 26 h, y `admin.sh logs` revisa los logs.",
    cmds: ["set -euo pipefail", "$?", "df -h", "systemctl --failed", "journalctl -p err"] },
  { n: 14, unit: "U8", q: "¿Qué diferencia hay entre una máquina virtual y un contenedor? ¿Cómo desplegaron el SGRSI y por qué eligieron ese camino?",
    exp: "La VM virtualiza hardware con su propio kernel (GB, minutos); el contenedor comparte el kernel y aísla procesos (MB, segundos). Imagen contra contenedor. Compose con app y base, volumen con nombre y red propia. DMZ: separar lo expuesto de lo interno.",
    lux: "Podman rootless con un único ops/compose.yaml: db, migrate, api y web; volumen lux_pgdata; tres redes (lux_data y lux_app internas, lux_edge con salida). Se levanta con `admin.sh deploy up` o `podman compose up -d --build`. Podman: rootless, sin demonio y con systemd; el mismo archivo valida con docker compose config. DMZ: solo web toca lux_edge y la base está aislada; ops/verificar-redes.sh lo prueba. Evaluación completa en docs/EVALUACION-CONTENEDORES.md.",
    cmds: ["podman compose up -d", "podman ps", "admin.sh deploy estado", "ops/verificar-redes.sh"] },
  { n: 15, unit: "U9", q: "Se rompió el disco del servidor principal. Contame, paso a paso, cómo recuperás el SGRSI a partir del servidor de respaldo.",
    exp: "Regla 3-2-1. Llegan por rsync o scp sobre SSH con llave dedicada. Pasos: servidor nuevo, traer la última copia, verificar integridad, restaurar configuración y código, instalar servicios o Docker, importar el .sql, comprobar con SELECT COUNT(*) y reprogramar respaldos. RPO y RTO.",
    lux: "El servidor de respaldo (segunda VM) recibe por rsync sobre SSH con llave solo de escritura (rrsync), valida con sha256 y gzip -t, y guarda en almacen (o rechazados), con rotación 7 y 4 y auditoría diaria. Recuperación: servidor nuevo con Debian y red; `admin.sh respaldo remoto restaurar <id> [destino]` trae la corrida y verifica las sumas; restaurar configuración y código; `admin.sh deploy up`; `backup.sh restaurar <dump.gz>`; comprobar datos con una consulta; reinstalar cron. RPO: hasta 24 h (respaldo diario). RTO: medirlo en una prueba real.",
    cmds: ["rsync -av -e ssh", "sha256sum -c", "admin.sh respaldo remoto restaurar", "backup.sh restaurar"], todo: "Medir el RTO real con una restauración de prueba." },
];

